import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import * as api from "../utils/api";

function UserDashboard() {
  const [account, setAccount] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const loadMyAccount = async () => {
      try {
        const data = await api.fetchMyAccount();
        setAccount(data);
      } catch (error) {
        setError(api.messageFromError(error));
      } finally {
        setLoading(false);
      }
    };

    loadMyAccount();
  }, []);

  if (loading) {
    return (
      <div className="dashboard-container">
        <div className="loading-card">
          <div className="loader"></div>
          <p>Loading your account...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-header">
          <p className="dashboard-label">PERSONAL BANKING</p>
          <h1>User Dashboard</h1>
        </div>

        <div className="alert error">
          {error}
        </div>
      </div>
    );
  }

  if (!account) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-header">
          <p className="dashboard-label">PERSONAL BANKING</p>
          <h1>User Dashboard</h1>
        </div>

        <div className="empty-state">
          <h2>No Account Found</h2>
          <p>Your account information is not available.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">

      {/* HEADER */}
      <div className="dashboard-header">
        <div>
          <p className="dashboard-label">PERSONAL BANKING</p>
          <h1>Welcome back, {account.accountHolderName}! 👋</h1>
          <p className="dashboard-subtitle">
            Manage your account and transactions from one place.
          </p>
        </div>
      </div>

      {/* ACCOUNT SUMMARY */}
      <div className="user-account-card">

        <div className="account-card-header">
          <div>
            <p className="card-label">MY ACCOUNT</p>
            <h2>{account.accountHolderName}</h2>
          </div>

          <span className="account-type-badge">
            {account.accountType}
          </span>
        </div>

        <div className="account-balance-section">
          <p className="balance-label">Available Balance</p>

          <h3 className="large-balance">
            ₹{Number(account.balance || 0).toFixed(2)}
          </h3>
        </div>

        <div className="account-info-grid">

          <div className="info-item">
            <span>Account Number</span>
            <strong>{account.accountNumber}</strong>
          </div>

          <div className="info-item">
            <span>Account Holder</span>
            <strong>{account.accountHolderName}</strong>
          </div>

          <div className="info-item">
            <span>Account Type</span>
            <strong>{account.accountType}</strong>
          </div>

        </div>

        <div className="dashboard-actions">

          <Link
            className="action-button"
            to={`/accounts/${account.accountId}/deposit`}
          >
            <span className="action-icon">＋</span>
            <span>
              <strong>Deposit</strong>
              <small>Add money</small>
            </span>
          </Link>

          <Link
            className="action-button"
            to={`/accounts/${account.accountId}/withdraw`}
          >
            <span className="action-icon">−</span>
            <span>
              <strong>Withdraw</strong>
              <small>Take out money</small>
            </span>
          </Link>

          <Link
            className="action-button"
            to={`/accounts/${account.accountId}/transfer`}
          >
            <span className="action-icon">→</span>
            <span>
              <strong>Transfer</strong>
              <small>Send money</small>
            </span>
          </Link>

          <Link
            className="action-button"
            to={`/accounts/${account.accountId}/transactions`}
          >
            <span className="action-icon">↗</span>
            <span>
              <strong>Transactions</strong>
              <small>View history</small>
            </span>
          </Link>

        </div>

      </div>

    </div>
  );
}

export default UserDashboard;
